            i0.ɵɵelementEnd()()()()();
            i0.ɵɵelementStart(218, "p", 24);
            i0.ɵɵtext(219, " If we ever want to use your information for a purpose that is not listed above, we will tell you first and, where required, ask for your permission. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(220, "section", 46)(221, "h2", 23);
            i0.ɵɵtext(222, "5. Cookies and similar technologies");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(223, "p", 24);
            i0.ɵɵtext(224, " A cookie is a small file the site stores in your browser so it can remember something between one page and the next. We use three kinds: ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(225, "div", 47)(226, "div", 48)(227, "p", 49);
            i0.ɵɵtext(228, "Strictly necessary cookies");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(229, "p", 50);
            i0.ɵɵtext(230, " These make the site work: remembering your language preference, remembering that you already dismissed the cookie notice, and protecting forms against automated submissions. They cannot be turned off without breaking the site and do not require your consent. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(231, "div", 48)(232, "p", 49);
            i0.ɵɵtext(233, "Analytics cookies");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(234, "p", 50);
            i0.ɵɵtext(235, " These tell us how many people visit each page and how they move through the site, in aggregate. We use them to learn which content works. You can refuse them without losing any functionality. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(236, "div", 48)(237, "p", 49);
            i0.ɵɵtext(238, "Marketing cookies");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(239, "p", 50);
            i0.ɵɵtext(240, " These let us measure how our campaigns perform and show relevant ads on other platforms. They are only set if you accept them. ");
            i0.ɵɵelementEnd()()();
            i0.ɵɵelementStart(241, "h3", 31);
            i0.ɵɵtext(242, "How to control them");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(243, "p", 30);
            i0.ɵɵtext(244, " You can change your choice at any time from the cookie notice on the site, or block and delete cookies from your browser settings (Chrome, Safari, Firefox and Edge all allow this under privacy settings). If you block everything, some parts of the site may not behave as expected. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(245, "p", 30);
            i0.ɵɵtext(246, " We also honor ");
            i0.ɵɵelementStart(247, "span", 26);
            i0.ɵɵtext(248, "Global Privacy Control");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(249, " (GPC) signals sent by your browser as an opt-out of analytics and marketing cookies. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(250, "section", 51)(251, "h2", 23);
            i0.ɵɵtext(252, "6. Who we share information with");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(253, "p", 24);
            i0.ɵɵtext(254, " We do not sell your information. We share it only with service providers who work on our behalf and may use it only as we instruct them: ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(255, "ul", 52)(256, "li")(257, "span", 26);
