            i0.ɵɵelementEnd();
            i0.ɵɵtext(259, ", which run the site and its logs.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(260, "li")(261, "span", 26);
            i0.ɵɵtext(262, "Supabase");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(263, ", which hosts the mobile application's database, user authentication and file storage.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(264, "li")(265, "span", 26);
            i0.ɵɵtext(266, "Email providers");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(267, ", so we can receive and answer your messages.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(268, "li")(269, "span", 26);
            i0.ɵɵtext(270, "Web analytics tools");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(271, ", to measure site usage.");
