            i0.ɵɵelementStart(276, "li")(277, "span", 26);
            i0.ɵɵtext(278, "Advertising platforms");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(279, ", only if you accepted marketing cookies.");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(280, "p", 24);
            i0.ɵɵtext(281, " We may also disclose information when a competent authority lawfully requires it, or when it is necessary to establish or defend our legal rights. If our business is ever sold or merged, your information may transfer to the acquirer under this same policy. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(282, "p", 53);
            i0.ɵɵtext(283, " Want the current list of the specific providers we use? Ask at ");
