            i0.ɵɵtext(285);
            i0.ɵɵelementEnd();
            i0.ɵɵtext(286, " and we will send it. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(287, "section", 54)(288, "h2", 23);
            i0.ɵɵtext(289, "7. International visitors");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(290, "p", 24);
            i0.ɵɵtext(291, " Our site and the services behind it are operated from the United States. If you visit from outside the U.S., your information is transferred to and processed in the United States, whose privacy laws may differ from those of your country. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(292, "p", 24);
            i0.ɵɵtext(293, " Some of our providers also run servers in other regions. Where that happens, we choose providers that offer contractual security and confidentiality commitments equivalent to our own. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(294, "section", 55)(295, "h2", 23);
            i0.ɵɵtext(296, "8. How long we keep information");
