            i0.ɵɵelementStart(336, "td", 45);
            i0.ɵɵtext(337, "As long as the applicable law requires");
            i0.ɵɵelementEnd()()()()();
            i0.ɵɵelementStart(338, "p", 24);
            i0.ɵɵtext(339, " Once the period ends, the information is destroyed or anonymized so it can no longer identify you, consistent with Massachusetts law on the destruction of records containing personal information (M.G.L. c. 93I). ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(340, "section", 57)(341, "h2", 23);
            i0.ɵɵtext(342, "9. How we protect information");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(343, "p", 24);
            i0.ɵɵtext(344, " We maintain a written information security program with administrative, technical and physical safeguards, as required of anyone holding personal information about Massachusetts residents (201 CMR 17.00). In practice that means: ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(345, "ul", 58)(346, "li");
            i0.ɵɵtext(347, "HTTPS/TLS encryption in transit across the whole site.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(348, "li");
            i0.ɵɵtext(349, "Access limited to the people who need it to do their job.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(350, "li");
            i0.ɵɵtext(351, "Multi-factor authentication on the tools where contact records live.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(352, "li");
            i0.ɵɵtext(353, "Regular backups and patching of the site's components.");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(354, "p", 24);
            i0.ɵɵtext(355, " No system connected to the internet is invulnerable. If a security incident materially affects your personal information, we will notify you and the appropriate authorities as required by Massachusetts breach notification law (M.G.L. c. 93H) and any other law that applies to you, together with what we are doing about it. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(356, "section", 59)(357, "h2", 23);
            i0.ɵɵtext(358, "10. Your privacy rights");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(359, "p", 24);
            i0.ɵɵtext(360, " We extend the following rights to ");
            i0.ɵɵelementStart(361, "span", 26);
            i0.ɵɵtext(362, "every visitor");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(363, ", not only to residents of states that already mandate them: ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(364, "ul", 52)(365, "li")(366, "span", 26);
            i0.ɵɵtext(367, "Know and access:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(368, " find out what information we hold about you and what we do with it.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(369, "li")(370, "span", 26);
            i0.ɵɵtext(371, "Correct:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(372, " fix information that is inaccurate or incomplete.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(373, "li")(374, "span", 26);
            i0.ɵɵtext(375, "Delete:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(376, " have your information erased when we no longer need it.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(377, "li")(378, "span", 26);
            i0.ɵɵtext(379, "Opt out:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(380, " tell us to stop processing your information for a specific purpose.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(381, "li")(382, "span", 26);
            i0.ɵɵtext(383, "Portability:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(384, " receive a copy of your information in a common, machine-readable format.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(385, "li")(386, "span", 26);
            i0.ɵɵtext(387, "Withdraw consent:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(388, " revoke permission you gave us, without affecting what was done beforehand.");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(389, "li")(390, "span", 26);
            i0.ɵɵtext(391, "No retaliation:");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(392, " we will never charge you a different price or degrade your service for exercising any of these.");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(393, "p", 24);
            i0.ɵɵtext(394, " Because we do not sell or share personal information for cross-context behavioral advertising, there is no \"Do Not Sell or Share My Personal Information\" process to run \u2014 but if that ever changes, we will add one and say so here before it takes effect. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(395, "div", 60)(396, "p", 49);
            i0.ɵɵtext(397, "How to make a request");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(398, "p", 61);
            i0.ɵɵtext(399, " Email ");
            i0.ɵɵelementStart(400, "a", 62);
            i0.ɵɵtext(401);
            i0.ɵɵelementEnd();
            i0.ɵɵtext(402, " telling us which right you want to exercise and which email address you contacted us from. We may ask you to confirm your identity so we do not hand your data to someone else. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(403, "p", 61);
            i0.ɵɵtext(404, " We respond within ");
