            i0.ɵɵtext(406, "45 days");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(407, ", and will tell you if we need a single extension. There is no charge. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(408, "p", 61);
            i0.ɵɵtext(409, " You may use an authorized agent to submit a request on your behalf; we will ask for proof of their authority. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(410, "p", 24);
            i0.ɵɵtext(411, " To stop marketing email you do not need to write to us: use the unsubscribe link at the bottom of any message, as provided under the CAN-SPAM Act. ");
