            i0.ɵɵelementStart(425, "section", 66)(426, "h2", 23);
            i0.ɵɵtext(427, "13. Governing law");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(428, "p", 24);
            i0.ɵɵtext(429, " This policy is governed by the laws of the Commonwealth of Massachusetts and the applicable federal laws of the United States. There is no single comprehensive federal privacy statute in the U.S.; instead, the following apply to a site like ours: ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(430, "ul", 52)(431, "li")(432, "span", 26);
            i0.ɵɵtext(433, "201 CMR 17.00");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(434, " \u2014 Massachusetts standards for protecting the personal information of Commonwealth residents, which require a written information security program. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(435, "li")(436, "span", 26);
            i0.ɵɵtext(437, "M.G.L. c. 93H and c. 93I");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(438, " \u2014 Massachusetts data breach notification and secure destruction of records containing personal information. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(439, "li")(440, "span", 26);
            i0.ɵɵtext(441, "CAN-SPAM Act");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(442, " \u2014 rules for commercial email, including a working unsubscribe mechanism. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(443, "li")(444, "span", 26);
            i0.ɵɵtext(445, "COPPA");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(446, " \u2014 protection of children under 13 online. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(447, "li")(448, "span", 26);
            i0.ɵɵtext(449, "FTC Act, Section 5");
            i0.ɵɵelementEnd();
            i0.ɵɵtext(450, " \u2014 which makes this policy enforceable: we have to do what it says. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(451, "p", 24);
            i0.ɵɵtext(452, " Massachusetts does not yet have a comprehensive consumer privacy statute. A Massachusetts Data Privacy Act has passed both chambers of the legislature in separate versions and is being reconciled as of the date of this policy. We have written the rights in section 10 to meet what that bill and comparable state laws \u2014 such as the California Consumer Privacy Act \u2014 would require, so nothing about how we treat you needs to change when one of them takes effect. ");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(453, "p", 24);
            i0.ɵɵtext(454, " If you are a resident of California, Colorado, Connecticut, Virginia or another state with a comprehensive privacy law, exercise your rights through section 10 and tell us which state you are in; we will apply whatever that law adds. If you are in the European Union or the United Kingdom, the same channel applies, without prejudice to your right to complain to your national supervisory authority. ");
            i0.ɵɵelementEnd()();
            i0.ɵɵelementStart(455, "section", 67)(456, "h2", 23);
            i0.ɵɵtext(457, "14. Changes to this policy");
            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(458, "p", 24);
            i0.ɵɵtext(459, " We may update this policy when our practices, our tools or the applicable law change. The current version will always be the one published at ");
            i0.ɵɵelementStart(460, "span", 26);
            i0.ɵɵtext(461);
            i0.ɵɵelementEnd();
