            i0.ɵɵelementEnd();
            i0.ɵɵelementStart(463, "p", 24);
            i0.ɵɵtext(464, " If a change is material \u2014 a new purpose for using your information, for example \u2014 we will announce it on the site and, if we have your email from an active subscription, notify you there before it takes effect. ");
            i0.ɵɵelementEnd()();
