            i0.ɵɵtextInterpolate1("2.2 The ", ctx.brand, " mobile application");
            i0.ɵɵadvance(2);
            i0.ɵɵtextInterpolate1(" It also covers the ", ctx.brand, " mobile application for Android and iOS. Inside the app we collect only what is needed to run the service for the organization you work for: ");
            i0.ɵɵadvance(29);
            i0.ɵɵtextInterpolate1(" Where an organization licenses ", ctx.brand, " for its employees, that organization decides what gets recorded in its workspace; how it uses those records internally is governed by its service agreement with us and by its own policies. ");
            i0.ɵɵadvance(172);
            i0.ɵɵproperty("href", "mailto:" + ctx.privacyEmail, i0.ɵɵsanitizeUrl);
            i0.ɵɵadvance();
            i0.ɵɵtextInterpolate(ctx.privacyEmail);
            i0.ɵɵadvance(115);
            i0.ɵɵproperty("href", "mailto:" + ctx.privacyEmail, i0.ɵɵsanitizeUrl);
            i0.ɵɵadvance();
            i0.ɵɵtextInterpolate(ctx.privacyEmail);
            i0.ɵɵadvance(15);
            i0.ɵɵtextInterpolate1(" ", ctx.brand, " is a product for businesses and professionals. This site is not directed to children and we do not knowingly collect personal information from anyone under 18, or from children under 13 as defined by the Children's Online Privacy Protection Act (COPPA). If we learn that we have received information from a child, we delete it. If you are a parent or guardian and believe a child in your care sent us information, email ");
            i0.ɵɵadvance();
            i0.ɵɵproperty("href", "mailto:" + ctx.privacyEmail, i0.ɵɵsanitizeUrl);
            i0.ɵɵadvance();
