            i0.ɵɵadvance(6);
            i0.ɵɵtextInterpolate1(" Our site links to pages we do not control: social networks, integration documentation, external articles. Once you leave ", ctx.site, ", your information is governed by that site's privacy policy, not this one. We recommend reading it. ");
            i0.ɵɵadvance(37);
            i0.ɵɵtextInterpolate1("", ctx.site, "/privacidad");
            i0.ɵɵadvance(11);
