(() => { (typeof ngDevMode === "undefined" || ngDevMode) && i0.ɵsetClassMetadata(PrivacidadComponent, [{
        type: Component,
        args: [{ selector: 'app-privacidad', standalone: false, template: "<!--\n  Privacy Policy \u2014 M.I.A Tracker\n  Accent: emerald + lime, same as the landing navbar and footer.\n  The pt-16 on <article> clears the fixed header (h-16).\n-->\n\n<article class=\"bg-white text-slate-700 pt-16\">\n\n  <!-- ============ Header ============ -->\n  <header class=\"bg-emerald-900\">\n    <div class=\"mx-auto max-w-5xl px-6 py-16 sm:py-20\">\n      <a routerLink=\"/\"\n         class=\"inline-flex items-center gap-2 text-sm font-medium text-lime-300 hover:text-lime-200\">\n        <svg class=\"h-4 w-4\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\">\n          <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M10 19l-7-7m0 0l7-7m-7 7h18\" />\n        </svg>\n        Back to home\n      </a>\n\n      <h1 class=\"mt-6 text-4xl font-bold tracking-tight text-white sm:text-5xl\">\n        Privacy Policy\n      </h1>\n      <p class=\"mt-4 max-w-2xl text-lg leading-relaxed text-emerald-100\">\n        How {{ brand }} collects, uses and protects information about the people who visit\n        <span class=\"text-white\">miatracker.com</span>.\n      </p>\n\n      <dl class=\"mt-8 flex flex-wrap gap-x-10 gap-y-3 text-sm\">\n        <div>\n          <dt class=\"text-emerald-300\">Last updated</dt>\n          <dd class=\"mt-0.5 font-medium text-white\">{{ lastUpdated }}</dd>\n        </div>\n        <div>\n          <dt class=\"text-emerald-300\">Effective date</dt>\n          <dd class=\"mt-0.5 font-medium text-white\">{{ effectiveDate }}</dd>\n        </div>\n        <div>\n          <dt class=\"text-emerald-300\">Contact</dt>\n          <dd class=\"mt-0.5 font-medium text-white\">\n            <a [href]=\"'mailto:' + privacyEmail\" class=\"hover:text-lime-200\">{{ privacyEmail }}</a>\n          </dd>\n        </div>\n      </dl>\n    </div>\n  </header>\n\n  <!-- ============ Body ============ -->\n  <div class=\"mx-auto max-w-5xl px-6 py-12 lg:flex lg:gap-12 lg:py-16\">\n\n    <!-- Table of contents -->\n    <nav class=\"mb-12 lg:mb-0 lg:w-64 lg:shrink-0\" aria-label=\"Policy contents\">\n      <div class=\"lg:sticky lg:top-24\">\n        <p class=\"text-xs font-semibold uppercase tracking-wider text-slate-500\">Contents</p>\n        <ul class=\"mt-4 space-y-1 border-l border-slate-200\">\n          <li *ngFor=\"let s of sections\">\n            <a [href]=\"'#' + s.id\"\n               class=\"block border-l-2 border-transparent -ml-px py-1.5 pl-4 text-sm text-slate-600 hover:border-emerald-600 hover:text-emerald-700\">\n              {{ s.title }}\n            </a>\n          </li>\n        </ul>\n      </div>\n    </nav>\n\n    <!-- Text -->\n    <div class=\"min-w-0 flex-1 space-y-12 text-base leading-7\">\n\n      <p class=\"rounded-lg border border-slate-200 bg-slate-50 p-5 text-slate-600\">\n        This policy explains, in plain language, what happens to your information when you browse our\n        website or contact us through our forms. If anything here is unclear, email us at\n        <a [href]=\"'mailto:' + privacyEmail\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">{{ privacyEmail }}</a>\n        and we will walk you through it.\n      </p>\n\n      <!-- 1 -->\n      <section id=\"who-we-are\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">1. Who we are</h2>\n        <p class=\"mt-4\">\n          {{ brand }} (<em>Maintenance, Inventory &amp; Asset Tracker</em>) is a barcode-based inventory\n          and asset control solution. We are responsible for the personal information collected through\n          this website.\n        </p>\n        <ul class=\"mt-4 space-y-1\">\n          <li><span class=\"font-medium text-slate-900\">Controller:</span> {{ brand }}</li>\n          <li><span class=\"font-medium text-slate-900\">Website:</span> {{ site }}</li>\n          <li><span class=\"font-medium text-slate-900\">Mailing address:</span> 51 Pleasant St # 1117, Malden, MA 02148, United States</li>\n          <li>\n            <span class=\"font-medium text-slate-900\">Privacy contact:</span>\n            <a [href]=\"'mailto:' + privacyEmail\" class=\"text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">{{ privacyEmail }}</a>\n          </li>\n        </ul>\n      </section>\n\n      <!-- 2 -->\n      <section id=\"scope\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">2. Scope of this policy</h2>\n\n        <h3 class=\"mt-6 text-lg font-semibold text-slate-900\">2.1 This website</h3>\n        <p class=\"mt-3\">\n          This policy covers the <span class=\"font-medium text-slate-900\">public website</span>\n          {{ site }} and all of its pages: the home page, product and pricing pages, the contact form and\n          demo requests. It does not cover third-party sites we link to.\n        </p>\n\n        <h3 class=\"mt-8 text-lg font-semibold text-slate-900\">2.2 The {{ brand }} mobile application</h3>\n        <p class=\"mt-3\">\n          It also covers the {{ brand }} mobile application for Android and iOS. Inside the app we collect\n          only what is needed to run the service for the organization you work for:\n        </p>\n        <ul class=\"mt-3 list-disc space-y-1 pl-6 marker:text-slate-400\">\n          <li>\n            <span class=\"font-medium text-slate-900\">Account and profile:</span> email address,\n            authentication credentials, name, username, profile photo, company and assigned role.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">Operational data you enter:</span> products, barcodes\n            and QR codes, quantities and stock levels, storage locations and their coordinates, assets,\n            maintenance records, orders, transfers, restock requests and notes.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">Photos you attach</span> to items, assets or movement\n            records.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">Device permissions:</span> camera (to scan barcodes and\n            QR codes), photo library (to attach images), notifications (low-stock alerts) and location (to\n            tag a storage location or a maintenance visit). Each one is requested in context and can be\n            denied; only the feature that depends on it stops working.\n          </li>\n        </ul>\n        <p class=\"mt-3\">\n          Application data is stored with <span class=\"font-medium text-slate-900\">Supabase</span>, our\n          hosted database, authentication and file storage provider, which processes it on our behalf and\n          under our instructions. The app contains no advertising SDKs, no third-party analytics and no\n          cross-app tracking, and we do not sell or share the information it holds.\n        </p>\n        <p class=\"mt-3\">\n          You can delete your account and its data at any time from inside the app, or by request:\n          see\n          <a routerLink=\"/delete-account\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">Delete your account and data</a>,\n          which lists exactly what is erased, what is retained and for how long.\n        </p>\n        <p class=\"mt-3 text-slate-600\">\n          Where an organization licenses {{ brand }} for its employees, that organization decides what gets\n          recorded in its workspace; how it uses those records internally is governed by its service\n          agreement with us and by its own policies.\n        </p>\n      </section>\n\n      <!-- 3 -->\n      <section id=\"information\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">3. Information we collect</h2>\n\n        <h3 class=\"mt-6 text-lg font-semibold text-slate-900\">3.1 Information you give us</h3>\n        <p class=\"mt-3\">\n          When you fill in the contact form, request a demo or sign up for updates, we collect only what\n          you type into those fields:\n        </p>\n        <ul class=\"mt-3 list-disc space-y-1 pl-6 marker:text-slate-400\">\n          <li>Name</li>\n          <li>Email address</li>\n          <li>Phone number (optional)</li>\n          <li>Company, job title and size of your operation (optional)</li>\n          <li>The content of the message you send us</li>\n        </ul>\n        <p class=\"mt-3 text-slate-600\">\n          Please <span class=\"font-medium text-slate-900\">do not include sensitive information</span>\n          (health data, financial account numbers, government ID numbers) in the message field. We do not\n          need it to help you.\n        </p>\n\n        <h3 class=\"mt-8 text-lg font-semibold text-slate-900\">3.2 Information collected automatically</h3>\n        <p class=\"mt-3\">\n          Like any website, our server and analytics tools record technical details about your visit:\n        </p>\n        <ul class=\"mt-3 list-disc space-y-1 pl-6 marker:text-slate-400\">\n          <li>IP address (which can indicate an approximate country or city)</li>\n          <li>Browser type, operating system and device type</li>\n          <li>Pages viewed, time on page and navigation path</li>\n          <li>The page or campaign you arrived from (referrer, UTM parameters)</li>\n          <li>Date and time of the visit</li>\n        </ul>\n        <p class=\"mt-3 text-slate-600\">\n          We do not collect precise geolocation, and we do not use this website to build advertising\n          profiles about identified individuals.\n        </p>\n\n        <h3 class=\"mt-8 text-lg font-semibold text-slate-900\">3.3 What we do not do</h3>\n        <ul class=\"mt-3 list-disc space-y-1 pl-6 marker:text-slate-400\">\n          <li>We do not sell or rent your personal information to anyone.</li>\n          <li>We do not buy contact lists for cold outreach.</li>\n          <li>We do not use your information for automated decisions that produce legal effects about you.</li>\n        </ul>\n      </section>\n\n      <!-- 4 -->\n      <section id=\"how-we-use\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">4. How we use your information</h2>\n        <div class=\"mt-4 overflow-x-auto\">\n          <table class=\"w-full min-w-[36rem] border-collapse text-left text-sm\">\n            <thead>\n              <tr class=\"border-b border-slate-300\">\n                <th class=\"py-3 pr-4 font-semibold text-slate-900\">Purpose</th>\n                <th class=\"py-3 pr-4 font-semibold text-slate-900\">Information used</th>\n                <th class=\"py-3 font-semibold text-slate-900\">Why we are allowed to</th>\n              </tr>\n            </thead>\n            <tbody class=\"divide-y divide-slate-200\">\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Answer your question or schedule a demo</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">Form details</td>\n                <td class=\"py-3 align-top text-slate-600\">You asked us to, by submitting the form</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Send you a quote or commercial proposal</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">Form details</td>\n                <td class=\"py-3 align-top text-slate-600\">Steps taken at your request before a contract</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Send product news or marketing email</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">Name and email address</td>\n                <td class=\"py-3 align-top text-slate-600\">Your sign-up, which you can withdraw at any time</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Measure site usage and improve content</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">Aggregated technical and navigation data</td>\n                <td class=\"py-3 align-top text-slate-600\">Our legitimate interest in running the site</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Prevent spam, abuse and attacks on the site</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">IP address and server logs</td>\n                <td class=\"py-3 align-top text-slate-600\">Our legitimate interest in security</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Meet legal obligations or lawful requests</td>\n                <td class=\"py-3 pr-4 align-top text-slate-600\">Whatever the law requires</td>\n                <td class=\"py-3 align-top text-slate-600\">Legal obligation</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"mt-4\">\n          If we ever want to use your information for a purpose that is not listed above, we will tell you\n          first and, where required, ask for your permission.\n        </p>\n      </section>\n\n      <!-- 5 -->\n      <section id=\"cookies\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">5. Cookies and similar technologies</h2>\n        <p class=\"mt-4\">\n          A cookie is a small file the site stores in your browser so it can remember something between\n          one page and the next. We use three kinds:\n        </p>\n\n        <div class=\"mt-6 space-y-4\">\n          <div class=\"rounded-lg border border-slate-200 p-5\">\n            <p class=\"font-semibold text-slate-900\">Strictly necessary cookies</p>\n            <p class=\"mt-1 text-slate-600\">\n              These make the site work: remembering your language preference, remembering that you already\n              dismissed the cookie notice, and protecting forms against automated submissions. They cannot\n              be turned off without breaking the site and do not require your consent.\n            </p>\n          </div>\n          <div class=\"rounded-lg border border-slate-200 p-5\">\n            <p class=\"font-semibold text-slate-900\">Analytics cookies</p>\n            <p class=\"mt-1 text-slate-600\">\n              These tell us how many people visit each page and how they move through the site, in\n              aggregate. We use them to learn which content works. You can refuse them without losing any\n              functionality.\n            </p>\n          </div>\n          <div class=\"rounded-lg border border-slate-200 p-5\">\n            <p class=\"font-semibold text-slate-900\">Marketing cookies</p>\n            <p class=\"mt-1 text-slate-600\">\n              These let us measure how our campaigns perform and show relevant ads on other platforms.\n              They are only set if you accept them.\n            </p>\n          </div>\n        </div>\n\n        <h3 class=\"mt-8 text-lg font-semibold text-slate-900\">How to control them</h3>\n        <p class=\"mt-3\">\n          You can change your choice at any time from the cookie notice on the site, or block and delete\n          cookies from your browser settings (Chrome, Safari, Firefox and Edge all allow this under\n          privacy settings). If you block everything, some parts of the site may not behave as expected.\n        </p>\n        <p class=\"mt-3\">\n          We also honor <span class=\"font-medium text-slate-900\">Global Privacy Control</span> (GPC)\n          signals sent by your browser as an opt-out of analytics and marketing cookies.\n        </p>\n      </section>\n\n      <!-- 6 -->\n      <section id=\"sharing\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">6. Who we share information with</h2>\n        <p class=\"mt-4\">\n          We do not sell your information. We share it only with service providers who work on our behalf\n          and may use it only as we instruct them:\n        </p>\n        <ul class=\"mt-4 list-disc space-y-2 pl-6 marker:text-slate-400\">\n          <li><span class=\"font-medium text-slate-900\">Hosting and infrastructure providers</span>, which run the site and its logs.</li>\n          <li><span class=\"font-medium text-slate-900\">Supabase</span>, which hosts the mobile application's database, user authentication and file storage.</li>\n          <li><span class=\"font-medium text-slate-900\">Email providers</span>, so we can receive and answer your messages.</li>\n          <li><span class=\"font-medium text-slate-900\">Web analytics tools</span>, to measure site usage.</li>\n          <li><span class=\"font-medium text-slate-900\">CRM and sales tools</span>, to follow up on your request.</li>\n          <li><span class=\"font-medium text-slate-900\">Advertising platforms</span>, only if you accepted marketing cookies.</li>\n        </ul>\n        <p class=\"mt-4\">\n          We may also disclose information when a competent authority lawfully requires it, or when it is\n          necessary to establish or defend our legal rights. If our business is ever sold or merged, your\n          information may transfer to the acquirer under this same policy.\n        </p>\n        <p class=\"mt-4 text-slate-600\">\n          Want the current list of the specific providers we use? Ask at\n          <a [href]=\"'mailto:' + privacyEmail\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">{{ privacyEmail }}</a>\n          and we will send it.\n        </p>\n      </section>\n\n      <!-- 7 -->\n      <section id=\"transfers\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">7. International visitors</h2>\n        <p class=\"mt-4\">\n          Our site and the services behind it are operated from the United States. If you visit from\n          outside the U.S., your information is transferred to and processed in the United States, whose\n          privacy laws may differ from those of your country.\n        </p>\n        <p class=\"mt-4\">\n          Some of our providers also run servers in other regions. Where that happens, we choose providers\n          that offer contractual security and confidentiality commitments equivalent to our own.\n        </p>\n      </section>\n\n      <!-- 8 -->\n      <section id=\"retention\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">8. How long we keep information</h2>\n        <div class=\"mt-4 overflow-x-auto\">\n          <table class=\"w-full min-w-[30rem] border-collapse text-left text-sm\">\n            <thead>\n              <tr class=\"border-b border-slate-300\">\n                <th class=\"py-3 pr-4 font-semibold text-slate-900\">Type of information</th>\n                <th class=\"py-3 font-semibold text-slate-900\">Retention period</th>\n              </tr>\n            </thead>\n            <tbody class=\"divide-y divide-slate-200\">\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Form inquiries that do not become business</td>\n                <td class=\"py-3 align-top text-slate-600\">24 months from last contact</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Contacts subscribed to marketing email</td>\n                <td class=\"py-3 align-top text-slate-600\">Until you unsubscribe</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Server and security logs</td>\n                <td class=\"py-3 align-top text-slate-600\">Up to 12 months</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Aggregated analytics data</td>\n                <td class=\"py-3 align-top text-slate-600\">Up to 26 months</td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Account and data inside the mobile application</td>\n                <td class=\"py-3 align-top text-slate-600\">\n                  Until you delete the account &mdash; see\n                  <a routerLink=\"/delete-account\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">Delete your account and data</a>\n                </td>\n              </tr>\n              <tr>\n                <td class=\"py-3 pr-4 align-top\">Records with a legal or accounting obligation</td>\n                <td class=\"py-3 align-top text-slate-600\">As long as the applicable law requires</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"mt-4\">\n          Once the period ends, the information is destroyed or anonymized so it can no longer identify\n          you, consistent with Massachusetts law on the destruction of records containing personal\n          information (M.G.L. c. 93I).\n        </p>\n      </section>\n\n      <!-- 9 -->\n      <section id=\"security\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">9. How we protect information</h2>\n        <p class=\"mt-4\">\n          We maintain a written information security program with administrative, technical and physical\n          safeguards, as required of anyone holding personal information about Massachusetts residents\n          (201 CMR 17.00). In practice that means:\n        </p>\n        <ul class=\"mt-4 list-disc space-y-1 pl-6 marker:text-slate-400\">\n          <li>HTTPS/TLS encryption in transit across the whole site.</li>\n          <li>Access limited to the people who need it to do their job.</li>\n          <li>Multi-factor authentication on the tools where contact records live.</li>\n          <li>Regular backups and patching of the site's components.</li>\n        </ul>\n        <p class=\"mt-4\">\n          No system connected to the internet is invulnerable. If a security incident materially affects\n          your personal information, we will notify you and the appropriate authorities as required by\n          Massachusetts breach notification law (M.G.L. c. 93H) and any other law that applies to you,\n          together with what we are doing about it.\n        </p>\n      </section>\n\n      <!-- 10 -->\n      <section id=\"rights\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">10. Your privacy rights</h2>\n        <p class=\"mt-4\">\n          We extend the following rights to <span class=\"font-medium text-slate-900\">every visitor</span>,\n          not only to residents of states that already mandate them:\n        </p>\n        <ul class=\"mt-4 list-disc space-y-2 pl-6 marker:text-slate-400\">\n          <li><span class=\"font-medium text-slate-900\">Know and access:</span> find out what information we hold about you and what we do with it.</li>\n          <li><span class=\"font-medium text-slate-900\">Correct:</span> fix information that is inaccurate or incomplete.</li>\n          <li><span class=\"font-medium text-slate-900\">Delete:</span> have your information erased when we no longer need it.</li>\n          <li><span class=\"font-medium text-slate-900\">Opt out:</span> tell us to stop processing your information for a specific purpose.</li>\n          <li><span class=\"font-medium text-slate-900\">Portability:</span> receive a copy of your information in a common, machine-readable format.</li>\n          <li><span class=\"font-medium text-slate-900\">Withdraw consent:</span> revoke permission you gave us, without affecting what was done beforehand.</li>\n          <li><span class=\"font-medium text-slate-900\">No retaliation:</span> we will never charge you a different price or degrade your service for exercising any of these.</li>\n        </ul>\n        <p class=\"mt-4\">\n          Because we do not sell or share personal information for cross-context behavioral advertising,\n          there is no \"Do Not Sell or Share My Personal Information\" process to run \u2014 but if that ever\n          changes, we will add one and say so here before it takes effect.\n        </p>\n\n        <div class=\"mt-6 rounded-lg border border-emerald-200 bg-emerald-50 p-5\">\n          <p class=\"font-semibold text-slate-900\">How to make a request</p>\n          <p class=\"mt-2 text-slate-700\">\n            Email\n            <a [href]=\"'mailto:' + privacyEmail\" class=\"font-medium text-emerald-800 underline underline-offset-2\">{{ privacyEmail }}</a>\n            telling us which right you want to exercise and which email address you contacted us from. We\n            may ask you to confirm your identity so we do not hand your data to someone else.\n          </p>\n          <p class=\"mt-2 text-slate-700\">\n            We respond within <span class=\"font-medium\">45 days</span>, and will tell you if we need a\n            single extension. There is no charge.\n          </p>\n          <p class=\"mt-2 text-slate-700\">\n            You may use an authorized agent to submit a request on your behalf; we will ask for proof of\n            their authority.\n          </p>\n        </div>\n\n        <p class=\"mt-4\">\n          To stop marketing email you do not need to write to us: use the unsubscribe link at the bottom\n          of any message, as provided under the CAN-SPAM Act.\n        </p>\n      </section>\n\n      <!-- 11 -->\n      <section id=\"children\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">11. Children\u2019s privacy</h2>\n        <p class=\"mt-4\">\n          {{ brand }} is a product for businesses and professionals. This site is not directed to children\n          and we do not knowingly collect personal information from anyone under 18, or from children\n          under 13 as defined by the Children's Online Privacy Protection Act (COPPA). If we learn that we\n          have received information from a child, we delete it. If you are a parent or guardian and\n          believe a child in your care sent us information, email\n          <a [href]=\"'mailto:' + privacyEmail\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">{{ privacyEmail }}</a>.\n        </p>\n      </section>\n\n      <!-- 12 -->\n      <section id=\"links\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">12. Third-party links</h2>\n        <p class=\"mt-4\">\n          Our site links to pages we do not control: social networks, integration documentation, external\n          articles. Once you leave {{ site }}, your information is governed by that site's privacy policy,\n          not this one. We recommend reading it.\n        </p>\n      </section>\n\n      <!-- 13 -->\n      <section id=\"legal\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">13. Governing law</h2>\n        <p class=\"mt-4\">\n          This policy is governed by the laws of the Commonwealth of Massachusetts and the applicable\n          federal laws of the United States. There is no single comprehensive federal privacy statute in\n          the U.S.; instead, the following apply to a site like ours:\n        </p>\n        <ul class=\"mt-4 list-disc space-y-2 pl-6 marker:text-slate-400\">\n          <li>\n            <span class=\"font-medium text-slate-900\">201 CMR 17.00</span> \u2014 Massachusetts standards for\n            protecting the personal information of Commonwealth residents, which require a written\n            information security program.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">M.G.L. c. 93H and c. 93I</span> \u2014 Massachusetts data\n            breach notification and secure destruction of records containing personal information.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">CAN-SPAM Act</span> \u2014 rules for commercial email,\n            including a working unsubscribe mechanism.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">COPPA</span> \u2014 protection of children under 13\n            online.\n          </li>\n          <li>\n            <span class=\"font-medium text-slate-900\">FTC Act, Section 5</span> \u2014 which makes this policy\n            enforceable: we have to do what it says.\n          </li>\n        </ul>\n        <p class=\"mt-4\">\n          Massachusetts does not yet have a comprehensive consumer privacy statute. A Massachusetts Data\n          Privacy Act has passed both chambers of the legislature in separate versions and is being\n          reconciled as of the date of this policy. We have written the rights in section 10 to meet what\n          that bill and comparable state laws \u2014 such as the California Consumer Privacy Act \u2014 would\n          require, so nothing about how we treat you needs to change when one of them takes effect.\n        </p>\n        <p class=\"mt-4\">\n          If you are a resident of California, Colorado, Connecticut, Virginia or another state with a\n          comprehensive privacy law, exercise your rights through section 10 and tell us which state you\n          are in; we will apply whatever that law adds. If you are in the European Union or the United\n          Kingdom, the same channel applies, without prejudice to your right to complain to your national\n          supervisory authority.\n        </p>\n      </section>\n\n      <!-- 14 -->\n      <section id=\"changes\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">14. Changes to this policy</h2>\n        <p class=\"mt-4\">\n          We may update this policy when our practices, our tools or the applicable law change. The\n          current version will always be the one published at\n          <span class=\"font-medium text-slate-900\">{{ site }}/privacidad</span>, with its last-updated\n          date at the top.\n        </p>\n        <p class=\"mt-4\">\n          If a change is material \u2014 a new purpose for using your information, for example \u2014 we will\n          announce it on the site and, if we have your email from an active subscription, notify you there\n          before it takes effect.\n        </p>\n      </section>\n\n      <!-- 15 -->\n      <section id=\"contact\" class=\"scroll-mt-24\">\n        <h2 class=\"text-2xl font-bold tracking-tight text-slate-900\">15. Contact us</h2>\n        <p class=\"mt-4\">\n          For any question, request or complaint about privacy and personal information:\n        </p>\n        <div class=\"mt-4 rounded-lg border border-slate-200 bg-slate-50 p-5\">\n          <p class=\"font-semibold text-slate-900\">{{ addressLines[0] }}</p>\n          <p class=\"mt-1\">\n            <a [href]=\"'mailto:' + privacyEmail\" class=\"font-medium text-emerald-700 underline underline-offset-2 hover:text-emerald-800\">{{ privacyEmail }}</a>\n          </p>\n          <address class=\"mt-2 not-italic text-slate-600\">\n            51 Pleasant St # 1117<br>\n            Malden, MA 02148<br>\n            United States\n          </address>\n        </div>\n      </section>\n\n      <!-- Close -->\n      <div class=\"border-t border-slate-200 pt-8\">\n        <p class=\"text-sm text-slate-500\">\n          Last updated: {{ lastUpdated }}.\n        </p>\n        <a routerLink=\"/\"\n           class=\"mt-4 inline-flex items-center gap-2 rounded-lg bg-emerald-700 px-5 py-2.5 text-sm font-medium text-white hover:bg-emerald-800\">\n          Back to home\n        </a>\n      </div>\n\n    </div>\n  </div>\n</article>\n" }]
    }], () => [{ type: i1.Title }, { type: i1.Meta }], null); })();
